SELECT "Hatred_1"."Keyword" AS "Keyword",   "Hatred_1"."State_" AS "State_",   SUM(1) AS "TEMP_Per100000__Fatall___copy___2109769841__0_",   CAST(MAX("Hatred_1"."StatePopNum") AS BIGINT) AS "TEMP_Per100000__Fatall___copy___3451088709__0_",   CAST(MIN("Hatred_1"."StatePopNum") AS BIGINT) AS "TEMP_Per100000__Fatall___copy___3855970114__0_",   SUM(1) AS "cnt_Number_of_Records_ok" FROM "Hatred_1" WHERE (("Hatred_1"."Keyword" IN ('beaner', 'bimbo', 'camel jockey', 'chicks with dicks', 'coon', 'dyke', 'hag', 'hick', 'hillbillies', 'hillbilly', 'honky', 'lesbo', 'man in a dress', 'men in dresses', 'nigger', 'paki', 'porch monkey', 'rag head', 'raghead', 'redneck', 'retard', 'sand nigger', 'sandnigger', 'shemale', 'spic', 'towel head', 'towelhead', 'trailer trash', 'trannies', 'tranny', 'twat', 'wetback')) AND ((("Hatred_1"."State_" >= 'AK') AND ("Hatred_1"."State_" <= 'CT')) OR (("Hatred_1"."State_" >= 'DE') AND ("Hatred_1"."State_" <= 'WY')))) GROUP BY "Hatred_1"."Keyword",   "Hatred_1"."State_";
